"""Browser-only D1 native golden import, generated by upstream Writer/Loader in CI."""
import os
from pathlib import Path
from playwright.sync_api import sync_playwright

URL = os.environ.get("VIEWER_URL", "http://127.0.0.1:8123")
GOLDEN = Path(os.environ["GOLDEN_ROOT"])


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page(viewport={"width": 1550, "height": 950})
        page_errors = []
        page.on("pageerror", lambda error: page_errors.append(str(error)))
        page.goto(URL, wait_until="domcontentloaded")
        directory = page.locator("#native-directory")
        directory.set_input_files(str(GOLDEN / "synthetic-owner-det-v2"))
        page.get_by_role("heading", name="TraceStore v2 · synthetic-owner-det-v2", exact=True).wait_for(timeout=15000)
        assert "LOCAL NATIVE" in page.locator(".synthetic-badge").inner_text()
        assert "PROCEDURE_ENTER" in page.locator(".timeline").inner_text()
        assert "not owner-certified" in page.locator(".info-note").inner_text().lower()
        page.get_by_role("button", name="Raw records", exact=True).click()
        assert "PROCEDURE_ENTER" in page.locator(".timeline").inner_text()
        page.get_by_role("button", name="All owners", exact=True).click()
        page.locator(".timeline .event-meta").filter(has_text="ca-agent-demo").first.wait_for(timeout=10000)
        directory.set_input_files(str(GOLDEN / "synthetic-owner-model-v2"))
        page.get_by_role("heading", name="TraceStore v2 · synthetic-owner-model-v2", exact=True).wait_for(timeout=15000)
        assert "Model Interaction" in page.locator(".timeline").inner_text()
        page.get_by_role("button", name="Source", exact=True).click()
        assert "NATIVE_LOCAL" in page.locator(".source-preview").inner_text()
        assert not page_errors, page_errors
        print("NATIVE_VIEWER_UI_PASS owner-generated v2 folders, local only, native provenance, model pairing")
        browser.close()


if __name__ == "__main__":
    main()
